public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null) return res;
    boolean[] used = new boolean[nums.length];
    backtrack(nums, new ArrayList<>(), used, res);
    return res;
}

private void backtrack(int[] nums, List<Integer> current, boolean[] used, List<List<Integer>> res) {
    if (current.size() == nums.length) {
        res.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            backtrack(nums, current, used, res);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    int maxLen = first.length();
    for (int len = maxLen; len >= 1; len--) {
        Set<String> seen = new HashSet<>();
        for (int i = 0; i + len <= first.length(); i++) {
            String sub = first.substring(i, i + len);
            if (!seen.add(sub)) {
                continue; // skip duplicate substrings
            }
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (!(s.contains(sub) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;
    int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                // BFS/DFS to mark all connected '@'
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0];
                    int cc = pos[1];
                    for (int dir = 0; dir < 8; dir++) {
                        int nr = cr + dx[dir];
                        int nc = cc + dy[dir];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                            grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

