public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) return false;
    if (k <= 0) return false; // invalid divisor
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }
    // Check remainder 0
    if (count[0] % 2 != 0) return false;
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // k even and r == k/2
            if (count[r] % 2 != 0) return false;
        } else {
            if (count[r] != count[k - r]) return false;
        }
    }
    return true;
}

