public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // dp[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);
    int processed = 0;
    for (int num : nums) {
        processed++;
        int maxK = Math.min(n / 2, processed);
        for (int k = maxK; k >= 1; k--) {
            java.util.HashSet<Integer> prev = dp[k - 1];
            if (prev.isEmpty()) continue;
            java.util.HashSet<Integer> curr = dp[k];
            for (int s : prev) {
                curr.add(s + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
