public int minInsertions(String s) {
    int balance = 0;      // number of unmatched '('
    int insertions = 0;   // number of insertions needed
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance > 0) {
                balance--; // match with a previous '('
            } else {
                // need to insert a '(' before this ')'
                insertions++;
                // after insertion, this ')' is matched, so balance stays 0
            }
        }
    }
    // any remaining unmatched '(' need ')' inserted
    insertions += balance;
    return insertions;
}

