        return 0;
    }
    int currentMax = nums[0];
    int globalMax = nums[0];
    int currentMin = nums[0];
    int globalMin = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int num = nums[i];
        currentMax = Math.max(num, currentMax + num);
        globalMax = Math.max(globalMax, currentMax);
        currentMin = Math.min(num, currentMin + num);
        globalMin = Math.min(globalMin, currentMin);
    }
    return Math.max(globalMax, -globalMin);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) return 0;
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int next = fib.get(fib.size() - 1) + fib.get(fib.size() - 2);
        if (next > k) break;
        fib.add(next);
    }
    // Greedy subtraction
    int count = 0;
    int remaining = k;
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    int count = 0;
    for (int f : small) {
        count++;
        if (count == k) return f;
    }
    for (int i = large.size() - 1; i >= 0; i--) {
        count++;
        if (count == k) return large.get(i);
    }
    return -1;
}

