private int dfs(int index, java.util.Set<String> used, String s) {
    if (index == s.length()) {
        return used.size();
    }
    int best = 0;
    for (int i = index; i < s.length(); i++) {
        String sub = s.substring(index, i + 1);
        if (!used.contains(sub)) {
            used.add(sub);
            int res = dfs(i + 1, used, s);
            if (res > best) best = res;
            used.remove(sub);
        }
    }
    return best;
}

