}

public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    if (m == 0) return new int[0];
    int n = mat[0].length;
    if (n == 0) return new int[0];
    int[] res = new int[m * n];
    int idx = 0;
    for (int s = 0; s < m + n - 1; s++) {
        if (s % 2 == 0) {
            int i = Math.min(s, m - 1);
            int j = s - i;
            while (i >= 0 && j < n) {
                res[idx++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            int i = Math.max(0, s - (n - 1));
            int j = s - i;
            while (i < m && j >= 0) {
